package br.com.onda;
import java.net.*;
import java.util.*;
import java.util.regex.*;
import org.json.*;

/** Reads declared public media only; does not execute scripts, unwrap players or decrypt streams. */
final class PublicMediaPage {
 static final int LIMIT=1024*1024;
 static final class Candidate {final String url,extension;Candidate(String u,String e){url=u;extension=e;}}
 final String title;final List<Candidate> media;final List<String> youtube;
 private PublicMediaPage(String title,List<Candidate> media,Set<String> youtube){this.title=title;this.media=media;this.youtube=Collections.unmodifiableList(new ArrayList<>(youtube));}
 static String decode(String value){Matcher m=Pattern.compile("&#(x[0-9a-fA-F]{1,6}|[0-9]{1,7});").matcher(value);StringBuffer out=new StringBuffer();while(m.find()){try{String n=m.group(1);int c=n.startsWith("x")?Integer.parseInt(n.substring(1),16):Integer.parseInt(n);m.appendReplacement(out,Matcher.quoteReplacement(Character.isValidCodePoint(c)&&c>31?new String(Character.toChars(c)):""));}catch(Exception e){m.appendReplacement(out,"");}}m.appendTail(out);return out.toString().replace("&quot;","\"").replace("&#39;","'").replace("&apos;","'").replace("&lt;","<").replace("&gt;",">").replace("&amp;","&");}
 private static Map<String,String> attributes(String tag){Map<String,String> out=new HashMap<>();Matcher m=Pattern.compile("([A-Za-z_:][A-Za-z0-9_:.-]*)\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))").matcher(tag);while(m.find())out.put(m.group(1).toLowerCase(Locale.ROOT),decode(m.group(2)!=null?m.group(2):m.group(3)!=null?m.group(3):m.group(4)));return out;}
 static String fromMime(String mime){if(mime==null)return "";String t=mime.toLowerCase(Locale.ROOT).split(";",2)[0].trim();switch(t){case "video/mp4":case "video/x-m4v":return "mp4";case "audio/mp4":case "audio/x-m4a":return "m4a";case "audio/mpeg":return "mp3";case "audio/aac":case "audio/x-aac":case "audio/aacp":return "aac";default:return "";}}
 private static void add(List<Candidate> out,Set<String> seen,URI base,String raw,String hint,Set<String> youtube){if(raw==null||raw.length()>16384)return;try{URI uri=base.resolve(raw.trim());if(!MediaLinks.publicShape(uri)||uri.getPath().toLowerCase(Locale.ROOT).matches(".*\\.(m3u8|mpd|m3u|ts)$"))return;if(MediaLinks.isYoutube(uri.toString())){try{if(youtube.size()<12)youtube.add(DownloadLinks.canonical(uri.toString()));}catch(IllegalArgumentException ignored){}return;}if(out.size()>=12)return;String ext=MediaLinks.extension(uri.toString());if(ext.isEmpty())ext=fromMime(hint);if(ext.isEmpty())return;String url=uri.toASCIIString();if(seen.add(url))out.add(new Candidate(url,ext));}catch(Exception ignored){}}
 static PublicMediaPage parse(String html,String page){if(html==null||html.length()>LIMIT)throw new IllegalArgumentException("Página grande demais para a análise.");URI base=URI.create(page);if(!MediaLinks.publicShape(base))throw new IllegalArgumentException("Página inválida");List<Candidate> out=new ArrayList<>();Set<String> seen=new HashSet<>(),youtube=new LinkedHashSet<>();String title="Mídia da página";Matcher heading=Pattern.compile("(?is)<title\\b[^>]*>([^<]{0,1000})</title>").matcher(html);if(heading.find())title=decode(heading.group(1)).trim();
  Matcher tags=Pattern.compile("(?is)<(?:meta|video|audio|source|iframe)\\b[^>]{0,20000}>").matcher(html);while(tags.find()){String tag=tags.group();Map<String,String> a=attributes(tag);if(tag.toLowerCase(Locale.ROOT).startsWith("<meta")){String key=a.getOrDefault("property",a.getOrDefault("name","")).toLowerCase(Locale.ROOT);if(key.equals("og:title")&&a.containsKey("content"))title=a.get("content");if(key.equals("twitter:player"))try{if(!MediaLinks.isYoutube(base.resolve(a.getOrDefault("content","")).toString()))continue;}catch(Exception invalid){continue;}if(Arrays.asList("og:video","og:video:url","og:video:secure_url","og:audio","og:audio:url","og:audio:secure_url","twitter:player:stream","twitter:player").contains(key))add(out,seen,base,a.get("content"),key.contains("audio")?"audio/mp4":"video/mp4",youtube);}else if(tag.toLowerCase(Locale.ROOT).startsWith("<iframe")){String src=a.getOrDefault("src",a.get("data-src"));try{URI u=base.resolve(src);if(MediaLinks.isYoutube(u.toString()))add(out,seen,base,src,"",youtube);}catch(Exception ignored){}}else{String hint=a.get("type");if(hint==null&&tag.toLowerCase(Locale.ROOT).startsWith("<video"))hint="video/mp4";add(out,seen,base,a.getOrDefault("src",a.get("data-src")),hint,youtube);}}
  String lower=html.toLowerCase(Locale.ROOT);int cursor=0;for(int scanned=0;scanned<32;scanned++){int begin=lower.indexOf("<script",cursor);if(begin<0)break;int head=lower.indexOf('>',begin),end=lower.indexOf("</script>",Math.max(begin,head));if(head<0||end<0)break;cursor=end+9;if(head-begin>2048||end-head>262144)continue;Map<String,String> attrs=attributes(html.substring(begin,head+1));if(!"application/ld+json".equalsIgnoreCase(attrs.getOrDefault("type","").split(";",2)[0].trim()))continue;try{json(new JSONTokener(html.substring(head+1,end)).nextValue(),base,out,seen,youtube,0,new int[]{0});}catch(Exception ignored){}}

  if(title.trim().isEmpty())title="Mídia da página";return new PublicMediaPage(title.substring(0,Math.min(160,title.length())),out,youtube);
 }
 private static boolean schema(Object value,String expected){if(value instanceof JSONArray){JSONArray list=(JSONArray)value;for(int i=0;i<Math.min(list.length(),16);i++)if(schema(list.opt(i),expected))return true;return false;}if(!(value instanceof String))return false;String type=(String)value;return type.equalsIgnoreCase(expected)||type.equalsIgnoreCase("https://schema.org/"+expected)||type.equalsIgnoreCase("http://schema.org/"+expected);}
 private static void declared(Object value,URI base,List<Candidate> out,Set<String> seen,Set<String> youtube,String hint,int depth){if(depth>4)return;if(value instanceof String)add(out,seen,base,(String)value,hint,youtube);else if(value instanceof JSONArray){JSONArray list=(JSONArray)value;for(int i=0;i<Math.min(list.length(),12);i++)declared(list.opt(i),base,out,seen,youtube,hint,depth+1);}else if(value instanceof JSONObject){JSONObject o=(JSONObject)value;declared(o.opt("@id"),base,out,seen,youtube,hint,depth+1);declared(o.opt("url"),base,out,seen,youtube,hint,depth+1);}}
 private static void json(Object value,URI base,List<Candidate> out,Set<String> seen,Set<String> youtube,int depth,int[] count){if(depth>8||++count[0]>1000)return;if(value instanceof JSONArray){JSONArray list=(JSONArray)value;for(int i=0;i<list.length()&&count[0]<1000;i++)json(list.opt(i),base,out,seen,youtube,depth+1,count);}else if(value instanceof JSONObject){JSONObject object=(JSONObject)value;boolean video=schema(object.opt("@type"),"VideoObject"),audio=schema(object.opt("@type"),"AudioObject");if(video||audio){String hint=object.optString("encodingFormat",video?"video/mp4":"audio/mp4");declared(object.opt("contentUrl"),base,out,seen,youtube,hint,0);Object embed=object.opt("embedUrl");if(embed instanceof String)try{if(MediaLinks.isYoutube(base.resolve((String)embed).toString()))add(out,seen,base,(String)embed,"",youtube);}catch(Exception ignored){}Object encoding=object.opt("encoding");JSONArray enc=encoding instanceof JSONArray?(JSONArray)encoding:new JSONArray().put(encoding);for(int i=0;i<Math.min(enc.length(),12);i++){JSONObject item=enc.optJSONObject(i);if(item!=null)declared(item.opt("contentUrl"),base,out,seen,youtube,item.optString("encodingFormat",hint),0);}}for(Iterator<String> keys=object.keys();keys.hasNext()&&count[0]<1000;){Object child=object.opt(keys.next());if(child instanceof JSONObject||child instanceof JSONArray)json(child,base,out,seen,youtube,depth+1,count);}}}
}
